package com.oracle.observability.kafka.connect;

import static org.junit.jupiter.api.Assertions.*;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.util.ArrayList;
import java.util.List;
import org.apache.kafka.common.TopicPartition;
import org.apache.kafka.connect.errors.DataException;
import org.apache.kafka.connect.sink.SinkRecord;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;

class LogEventsChunkerTest {
    private final ObjectMapper json = new ObjectMapper();

    @ParameterizedTest
    @ValueSource(ints = {0, 1, 99, 100, 101, 250})
    void batchesAtCountBoundaryWithoutLossOrDuplication(int count) throws Exception {
        List<SinkRecord> records = TestFixtures.records(count);
        List<PreparedChunk> chunks = new LogEventsChunker(TestFixtures.config()).chunk(records);
        assertEquals((count + 99) / 100, chunks.size());
        List<String> actual = new ArrayList<>();
        for (PreparedChunk chunk : chunks) {
            JsonNode root = json.readTree(chunk.payload());
            assertFalse(root.has("logGroupId"));
            JsonNode event = root.path("logEvents").get(0);
            assertEquals("Kafka Hackathon Application Logs", event.path("logSourceName").asText());
            assertFalse(event.has("entityId"));
            assertEquals(chunk.recordCount(), event.path("logRecords").size());
            event.path("logRecords").forEach(item -> {
                assertTrue(item.isTextual());
                actual.add(item.asText());
            });
            assertTrue(chunk.payloadBytes() <= 1_048_576);
            assertTrue(chunk.recordCount() <= 100);
        }
        assertEquals(records.stream().map(r -> r.value().toString()).toList(), actual);
    }

    @Test
    void countsEscapedUtf8BytesAndAcceptsAnExactFit() throws Exception {
        String message = "quotes \" slashes \\ newlines\n unicode नमस्ते 🚀".repeat(5);
        SinkRecord record = TestFixtures.record(0, 0, message);
        int exact = new LogEventsChunker(TestFixtures.config()).chunk(List.of(record)).get(0).payloadBytes();
        var props = TestFixtures.properties();
        props.put(OracleObservabilitySinkConfig.MAX_BYTES, Integer.toString(exact));
        var chunker = new LogEventsChunker(new OracleObservabilitySinkConfig(props));
        var chunks = chunker.chunk(List.of(record, TestFixtures.record(0, 1, message)));
        assertEquals(2, chunks.size());
        for (PreparedChunk chunk : chunks) {
            assertEquals(exact, chunk.payloadBytes());
            assertEquals(message, json.readTree(chunk.payload()).at("/logEvents/0/logRecords/0").asText());
        }
        props.put(OracleObservabilitySinkConfig.MAX_BYTES, Integer.toString(exact - 1));
        assertThrows(DataException.class,
                () -> new LogEventsChunker(new OracleObservabilitySinkConfig(props)).chunk(List.of(record)));
    }

    @Test
    void includesCommaAndEnvelopeInByteLimit() {
        var records = List.of(TestFixtures.record(0, 0, "a".repeat(80)),
                TestFixtures.record(0, 1, "b".repeat(80)));
        int exact = new LogEventsChunker(TestFixtures.config()).chunk(records).get(0).payloadBytes();
        var props = TestFixtures.properties();
        props.put(OracleObservabilitySinkConfig.MAX_BYTES, Integer.toString(exact));
        assertEquals(1, new LogEventsChunker(new OracleObservabilitySinkConfig(props)).chunk(records).size());
        props.put(OracleObservabilitySinkConfig.MAX_BYTES, Integer.toString(exact - 1));
        assertEquals(2, new LogEventsChunker(new OracleObservabilitySinkConfig(props)).chunk(records).size());
    }

    @Test
    void separatesPartitionsAndPreservesTheirOrderWithOffsetGaps() throws Exception {
        List<SinkRecord> records = List.of(TestFixtures.record(0, 2, "a"), TestFixtures.record(1, 4, "b"),
                TestFixtures.record(0, 7, "c"));
        var chunks = new LogEventsChunker(TestFixtures.config()).chunk(records);
        assertEquals(2, chunks.size());
        assertEquals(new TopicPartition("la-hackathon-logs", 0), chunks.get(0).partition());
        assertEquals(2, chunks.get(0).firstOffset());
        assertEquals(7, chunks.get(0).lastOffset());
        assertEquals(List.of("a", "c"), json.convertValue(
                json.readTree(chunks.get(0).payload()).at("/logEvents/0/logRecords"), List.class));
    }

    @Test
    void tracksOriginalCoordinatesAfterTopicAndPartitionTransform() {
        SinkRecord original = TestFixtures.record(0, 17, "hello");
        SinkRecord transformed = original.newRecord("renamed", 2, original.keySchema(), original.key(),
                original.valueSchema(), original.value(), original.timestamp());
        PreparedChunk chunk = new LogEventsChunker(TestFixtures.config()).chunk(List.of(transformed)).get(0);
        assertEquals(new TopicPartition("la-hackathon-logs", 0), chunk.partition());
        assertEquals(17, chunk.firstOffset());
    }

    @Test
    void includesOnlyConfiguredOptionalFields() throws Exception {
        var props = TestFixtures.properties();
        props.put(OracleObservabilitySinkConfig.ENTITY_ID, "test-entity");
        props.put(OracleObservabilitySinkConfig.ENTITY_TYPE, "Host (Linux)");
        props.put(OracleObservabilitySinkConfig.LOG_PATH, "kafka-hackathon.log");
        props.put(OracleObservabilitySinkConfig.TIMEZONE, "UTC");
        props.put(OracleObservabilitySinkConfig.LOG_SET, "request-only");
        var chunks = new LogEventsChunker(new OracleObservabilitySinkConfig(props)).chunk(TestFixtures.records(1));
        JsonNode event = json.readTree(chunks.get(0).payload()).at("/logEvents/0");
        assertEquals("test-entity", event.path("entityId").asText());
        assertEquals("Host (Linux)", event.path("entityType").asText());
        assertEquals("kafka-hackathon.log", event.path("logPath").asText());
        assertEquals("UTC", event.path("timezone").asText());
        assertFalse(event.has("logSet"));
    }

    @Test
    void rejectsInvalidRecordsInsteadOfSilentlyDroppingThem() {
        var chunker = new LogEventsChunker(TestFixtures.config());
        for (Object value : new Object[] {null, 123, "", "broken\uD800"}) {
            assertThrows(DataException.class, () -> chunker.chunk(List.of(TestFixtures.record(0, 0, value))));
        }
        assertThrows(DataException.class, () -> chunker.chunk(List.of(
                TestFixtures.record(0, 4, "a"), TestFixtures.record(0, 4, "b"))));
    }

    @Test
    void payloadIsImmutableAndEachRequestHasItsOwnToken() {
        var chunks = new LogEventsChunker(TestFixtures.config()).chunk(TestFixtures.records(101));
        byte first = chunks.get(0).payload()[0];
        byte[] copy = chunks.get(0).payload();
        copy[0] = 'x';
        assertEquals(first, chunks.get(0).payload()[0]);
        assertNotEquals(chunks.get(0).retryToken(), chunks.get(1).retryToken());
    }

    @Test
    void rejectsEnvelopeLargerThanLimit() {
        var props = TestFixtures.properties();
        props.put(OracleObservabilitySinkConfig.MAX_BYTES, "128");
        props.put(OracleObservabilitySinkConfig.LOG_PATH, "x".repeat(200));
        assertThrows(DataException.class, () -> new LogEventsChunker(new OracleObservabilitySinkConfig(props)));
    }
}
